function Need($v){if(-not $v){throw 'TEST_ASSERT'}}
$script:passed=0;$script:failed=0
function Test([string]$Name,[scriptblock]$Body){try{& $Body;$script:passed++;"PASS $Name"}catch{$script:failed++;"FAIL $Name [$($_.Exception.GetType().Name)]"}}
function New-Fixture {
 $id='1'*32;$payloads=@{'Deployment/install-session0-v2.ps1'=[Text.Encoding]::UTF8.GetBytes('FAKE_INSTALLER')}
 foreach($i in 1..8){$payloads['Code/V2/fake'+$i+'.txt']=[Text.Encoding]::UTF8.GetBytes('FAKE_BYTES_'+$i)}
 $files=@{};foreach($n in $payloads.Keys){$files[$n]=Get-V2Hash $payloads[$n]}
 $m=@{schema=2;kind='LIMITLESS_SESSION0_V2_CANDIDATE';package_id=$id;epoch=('20261027-v2-'+$id);approval_id=('v2-install-'+$id);approved=$false;auto_start=$false;execution_mode='FAKE_ONLY';max_seconds=90;bot_account=[LimitlessV2Contract]::Account;code_root=[LimitlessV2Contract]::CodeRoot;state_root=[LimitlessV2Contract]::StateRoot;task_name=[LimitlessV2Contract]::TaskName;pipe_name=('LimitlessPlanningV2-'+$id);boot_approval_sha256=[LimitlessV2Contract]::BootSha;files_sha256=$files}
 $raw=[Text.UTF8Encoding]::new($false).GetBytes(($m|ConvertTo-Json -Depth 10 -Compress));$worker='S-1-5-21-111-222-333-1007';$admin='S-1-5-21-111-222-333-1001'
 $a=@{schema=2;kind='INSTALL_V2';approved=$true;approval_id=$m.approval_id;epoch=$m.epoch;manifest_sha256=(Get-V2Hash $raw);installer_sha256=$files['Deployment/install-session0-v2.ps1'];zip_sha256=('a'*64);worker_sid=$worker;admin_sid=$admin;expires_unix=1000300;preserve_v1_hold=$true}
 return @{manifest=$m;raw=$raw;payloads=$payloads;approval=$a;worker=$worker;admin=$admin;zip=('a'*64)}
}
function New-FakeApi($F){
 $api=[pscustomobject]@{fixture=$F;fault='';events=[Collections.Generic.List[string]]::new();consumed=$false;createdSid=$null;newAccount=$false;newTask=$false;published=$false;gateHeld=$false;leaseBusy=$false;leaseDisposals=0;otherProcesses=0;launchers=0;workerKnown=$true;namesFree=$true;newSid='S-1-5-21-111-222-333-1010';sddlExtra=$false;lastRecord=$null;before='OLD855|SID1008_DISABLED|INSTALL1_CONSUMED|AUTH_HOME_BOOT_SQLITE_PRESERVED';nativeCalls=0}
 $api|Add-Member ScriptMethod Context {return @{admin=($this.fault -ne 'nonadmin');worker_sid=$this.fixture.worker;admin_sid=$this.fixture.admin;worker_batch_present=($this.fault -ne 'worker_rights');worker_groups_users_only=($this.fault -ne 'worker_groups');now=1000000}}
 $api|Add-Member ScriptMethod Snapshot {if($this.fault -eq 'snapshot'){throw 'FAKE_SECRET_TOKEN'};return @{known=$true;old_bot_disabled=($this.fault -ne 'old_enabled');old_code_verified=$true;operational_preserved=$true;fingerprint=if($this.fault -eq 'damage' -and $this.published){'DAMAGED'}else{$this.before}}}
 $api|Add-Member ScriptMethod Fresh {param($m)if(-not $this.namesFree -or $this.newAccount -or $this.newTask -or $this.published){throw 'FAKE_COLLISION'};$this.events.Add('fresh')}
 $api|Add-Member ScriptMethod WorkerState {return @{known=$this.workerKnown;foreign_processes=$this.otherProcesses;other_launchable_tasks=$this.launchers}}
 $api|Add-Member ScriptMethod Consume {param($m,$sha)if($this.consumed){throw 'FAKE_CONSUMED'};$this.consumed=$true;$this.events.Add('consume')}
 $api|Add-Member ScriptMethod AcquireLease {param($sid)if($this.leaseBusy -or $this.gateHeld){throw 'FAKE_BUSY'};$this.gateHeld=$true;$this.events.Add('lease');$l=[pscustomobject]@{api=$this};$l|Add-Member ScriptMethod Dispose {$this.api.gateHeld=$false;$this.api.leaseDisposals++};return $l}
 $api|Add-Member ScriptMethod CreateAccount {param($n,$p)$this.events.Add('account');$this.newAccount=$true;$this.createdSid=$this.newSid;if($this.fault -eq 'account'){throw [ComponentModel.Win32Exception]::new(5,'FAKE_SECRET_TOKEN')};return @{sid=$this.newSid;name=$n;disabled=($this.fault -ne 'enabled_window');users_only=($this.fault -ne 'groups');fresh=$true}}
 $api|Add-Member ScriptMethod GrantBatch {param($sid,$w,$a)$this.events.Add('batch');if($this.fault -eq 'lsa'){throw [ComponentModel.Win32Exception]::new(1313,'FAKE_SECRET_TOKEN')}}
 $api|Add-Member ScriptMethod Publish {param($m,$raw,$payloads,$bot,$worker)$this.events.Add('publish');$sd=[LimitlessV2Contract]::FsSddl('code',$true,$worker,$bot);if($this.fault -eq 'code_acl'){$sd+='(A;OICI;FA;;;BU)'};[LimitlessV2Contract]::ExactSddl($sd,[LimitlessV2Contract]::FsSddl('code',$true,$worker,$bot));$this.published=$true;if($this.fault -eq 'publish'){throw 'FAKE_SECRET_TOKEN'}}
 $api|Add-Member ScriptMethod WriteBinding {param($bytes,$bot,$worker)$this.events.Add('binding');$b=[Text.Encoding]::UTF8.GetString($bytes);[LimitlessV2Contract]::Binding($b,[Text.Encoding]::UTF8.GetString($this.fixture.raw),(Get-V2Hash $this.fixture.raw));if($this.fault -eq 'binding'){throw 'FAKE_SECRET_TOKEN'}}
 $api|Add-Member ScriptMethod RegisterTask {param($m,$worker,$ms,$bs,$sd,$flags)$this.events.Add('register');if($flags -ne 50 -or $this.newTask){throw 'FAKE_DUPLICATE'};$this.newTask=$true;if($this.fault -eq 'register'){throw [ComponentModel.Win32Exception]::new(183,'FAKE_SECRET_TOKEN')};return @{name=$m.task_name;disabled=($this.fault -ne 'task_enabled');triggers=if($this.fault -eq 'triggers'){1}else{0};run_level=if($this.fault -eq 'elevated'){1}else{0};retries=0;principal=$worker;time_limit_seconds=if($this.fault -eq 'time_limit'){91}else{90};multiple_instances=if($this.fault -eq 'multiple'){1}else{2};allow_hard_terminate=($this.fault -ne 'hard_stop');action_pinned=($this.fault -ne 'action');sddl=if($this.fault -eq 'task_acl'){$sd+'(A;;GX;;;BU)'}else{$sd}}}
 $api|Add-Member ScriptMethod Verify {param($m,$b,$payloads,$bs)$this.events.Add('verify');if($this.fault -eq 'post'){throw 'FAKE_SECRET_TOKEN'}}
 $api|Add-Member ScriptMethod Record {param($r)$this.events.Add('record');if($this.fault -eq 'record'){throw 'FAKE_SECRET_TOKEN'};$this.lastRecord=($r|ConvertTo-Json -Depth 12)}
 return $api
}
function Run-Core($F,$Api){Invoke-V2InstallCore $Api $F.raw $F.payloads ($F.approval|ConvertTo-Json -Depth 8 -Compress) $F.zip}
Test 'actual-core-success-OS-SID-binding-private-task-readback-no-execution' {$f=New-Fixture;$a=New-FakeApi $f;$r=Run-Core $f $a;Need ($r.status -ceq 'V2_INSTALLED_DISABLED_FAKE_ONLY_NO_EXECUTION' -and $r.v1_preserved -and $r.accounts_created -eq 1 -and $r.tasks_registered -eq 1 -and $r.worker_calls -eq 0 -and $a.nativeCalls -eq 0 -and $a.leaseDisposals -eq 1);Need (($a.events -join ',') -ceq 'fresh,consume,lease,account,batch,publish,binding,register,verify,record')}
foreach($field in @('schema','code_root','state_root','bot_account','task_name','pipe_name','epoch','approval_id','execution_mode','approved','auto_start','max_seconds')){Test ('manifest-boundary-'+$field) {$f=New-Fixture;switch($field){'schema'{$f.manifest[$field]=1};'approved'{$f.manifest[$field]=$true};'auto_start'{$f.manifest[$field]=$true};'max_seconds'{$f.manifest[$field]=91};default{$f.manifest[$field]='V1_OR_OTHER'}};$f.raw=[Text.Encoding]::UTF8.GetBytes(($f.manifest|ConvertTo-Json -Depth 10 -Compress));$a=New-FakeApi $f;$r=Run-Core $f $a;Need ($r.status -eq 'HOLD' -and $a.events.Count -eq 0)}}
foreach($field in @('schema','kind','approved','approval_id','epoch','manifest_sha256','installer_sha256','zip_sha256','worker_sid','admin_sid','expires_unix','preserve_v1_hold')){Test ('approval-v1-v2-mixing-'+$field) {$f=New-Fixture;switch($field){'schema'{$f.approval[$field]=1};'approved'{$f.approval[$field]=$false};'preserve_v1_hold'{$f.approval[$field]=$false};'expires_unix'{$f.approval[$field]=999999};default{$f.approval[$field]='WRONG'}};$a=New-FakeApi $f;$r=Run-Core $f $a;Need ($r.status -eq 'HOLD' -and $a.events.Count -eq 0)}}
Test 'payload-byte-sha-before-effects' {$f=New-Fixture;$f.payloads['Code/V2/fake1.txt']=[byte[]]@(0);$a=New-FakeApi $f;$r=Run-Core $f $a;Need ($r.status -eq 'HOLD' -and $a.events.Count -eq 0)}
Test 'payload-extra-before-effects' {$f=New-Fixture;$f.payloads['Code/V2/extra.txt']=[byte[]]@(0);$a=New-FakeApi $f;$r=Run-Core $f $a;Need ($r.status -eq 'HOLD' -and $a.events.Count -eq 0)}
Test 'zero-length-runtime-file-is-preserved-as-empty-byte-array' {$f=New-Fixture;$f.payloads['Code/V2/fake1.txt']=[byte[]]::new(0);$f.manifest.files_sha256['Code/V2/fake1.txt']=Get-V2Hash $f.payloads['Code/V2/fake1.txt'];$f.raw=[Text.Encoding]::UTF8.GetBytes(($f.manifest|ConvertTo-Json -Depth 10 -Compress));$f.approval.manifest_sha256=Get-V2Hash $f.raw;$a=New-FakeApi $f;$r=Run-Core $f $a;Need ($r.status -eq 'V2_INSTALLED_DISABLED_FAKE_ONLY_NO_EXECUTION')}
foreach($mode in @('nonadmin','worker_rights','worker_groups','snapshot','old_enabled','account','enabled_window','groups','lsa','publish','binding','register','task_enabled','triggers','elevated','time_limit','multiple','hard_stop','action','post','record','damage','code_acl','task_acl')){Test ('failure-stage-'+$mode+'-hold-preserve-no-retry-secrets') {$f=New-Fixture;$a=New-FakeApi $f;$a.fault=$mode;$r=Run-Core $f $a;$j=$r|ConvertTo-Json -Depth 14;Need ($r.status -ceq 'HOLD' -and $j -notmatch 'FAKE_SECRET_TOKEN' -and $a.nativeCalls -eq 0);$oldCalls=@($a.events|Where-Object{$_ -eq 'register'}).Count;$null=Run-Core $f $a;Need (@($a.events|Where-Object{$_ -eq 'register'}).Count -eq $oldCalls)}}
foreach($mode in @('busy','launchers','unknown','lease','names')){Test ('worker-and-namespace-fence-'+$mode) {$f=New-Fixture;$a=New-FakeApi $f;switch($mode){'busy'{$a.otherProcesses=1};'launchers'{$a.launchers=1};'unknown'{$a.workerKnown=$false};'lease'{$a.leaseBusy=$true};'names'{$a.namesFree=$false}};$r=Run-Core $f $a;Need ($r.status -eq 'HOLD' -and -not $a.newAccount -and -not $a.newTask)}}
foreach($sid in @([LimitlessV2Contract]::OldBotSid,'S-1-5-21-111-222-333-1001','S-1-5-21-111-222-333-1007','S-1-5-18')){Test ('returned-OS-sid-collision-'+$sid) {$f=New-Fixture;$a=New-FakeApi $f;$a.newSid=$sid;$r=Run-Core $f $a;Need ($r.status -eq 'HOLD' -and -not $a.published -and -not $a.newTask)}}
Test 'duplicate-success-does-not-register-twice' {$f=New-Fixture;$a=New-FakeApi $f;$null=Run-Core $f $a;$r=Run-Core $f $a;Need ($r.status -eq 'HOLD' -and @($a.events|Where-Object{$_ -eq 'register'}).Count -eq 1)}
Test 'worker-lease-readback-closed-on-publish-failure' {$f=New-Fixture;$a=New-FakeApi $f;$a.fault='publish';$null=Run-Core $f $a;Need (-not $a.gateHeld -and $a.leaseDisposals -eq 1 -and $a.consumed)}
Test 'win32-code-preserved-message-redacted' {$f=New-Fixture;$a=New-FakeApi $f;$a.fault='lsa';$r=Run-Core $f $a;$j=$r|ConvertTo-Json -Depth 12;Need ($j -match '1313' -and $j -notmatch 'FAKE_SECRET_TOKEN' -and $r.stage -eq 'GRANT_NEW_SID_BATCH')}
Test 'shared-worker-provider-numeric-error-survives-HOLD' {$f=New-Fixture;$a=New-FakeApi $f;$a.workerKnown=$false;$a|Add-Member NoteProperty lastWorkerState @{errors=@(@{type='SYNTHETIC_QUERY';hresult=-2147024891;win32=5})};$r=Run-Core $f $a;Need ($r.status -eq 'HOLD' -and $r.worker_query_errors[0].win32 -eq 5 -and -not $a.newAccount)}
foreach($kind in @('private','code','state')){Test ('exact-native-sddl-contract-'+$kind) {$f=New-Fixture;$sd=[LimitlessV2Contract]::FsSddl($kind,$true,$f.worker,'S-1-5-21-111-222-333-1010');[LimitlessV2Contract]::ExactSddl($sd,$sd);$hit=$false;try{[LimitlessV2Contract]::ExactSddl(($sd+'(A;OICI;FA;;;BU)'),$sd)}catch{$hit=$true};Need $hit}}
Test 'protected-policy-utf16-implementation-source-pin' {Need ((Get-FileHash -LiteralPath (Join-Path $PSScriptRoot '../TrialAccountPolicy.cs')).Hash -ceq 'D9A0BC50137119BC28C17C5496B5FC20B4DA81925B806BC472A538C4415F850B')}
Test 'native-adapter-construction-has-no-method-property-collision-no-OS-call' {. (Join-Path $PSScriptRoot 'V2WindowsAdapter.ps1');$secret=[Security.SecureString]::new();$cred=[pscredential]::new('SYNTHETIC_USER',$secret);$a=New-V2WindowsAdapter 'FAKE_BUNDLE' $secret $cred;Need ($null -ne $a.PSObject.Methods['Context'] -and $null -ne $a.PSObject.Methods['Record'])}
Test 'shared-worker-tree-generation-own-root-and-child' {$p=[Collections.Generic.Dictionary[int,int]]::new();$p[10]=1;$p[11]=10;$t=[Collections.Generic.Dictionary[int,long]]::new();$t[10]=100;$t[11]=110;Need ([LimitlessV2WorkerFence]::AcceptSnapshot($p,$t,10))}
Test 'shared-worker-stale-parent-PID-reuse-rejected' {$p=[Collections.Generic.Dictionary[int,int]]::new();$p[10]=1;$p[11]=10;$t=[Collections.Generic.Dictionary[int,long]]::new();$t[10]=100;$t[11]=90;Need (-not [LimitlessV2WorkerFence]::AcceptSnapshot($p,$t,10))}
Test 'shared-worker-foreign-sibling-rejected' {$p=[Collections.Generic.Dictionary[int,int]]::new();$p[10]=1;$p[11]=1;$t=[Collections.Generic.Dictionary[int,long]]::new();$t[10]=100;$t[11]=110;Need (-not [LimitlessV2WorkerFence]::AcceptSnapshot($p,$t,10))}
Test 'shared-worker-empty-or-incomplete-provider-rejected' {$p=[Collections.Generic.Dictionary[int,int]]::new();$t=[Collections.Generic.Dictionary[int,long]]::new();Need (-not [LimitlessV2WorkerFence]::AcceptSnapshot($p,$t,10));$p[10]=1;Need (-not [LimitlessV2WorkerFence]::AcceptSnapshot($p,$t,10))}
foreach($ps in Get-ChildItem -LiteralPath $PSScriptRoot -Filter '*.ps1'){Test ('parse-no-exit-'+$ps.Name) {$t=$null;$e=$null;$a=[Management.Automation.Language.Parser]::ParseFile($ps.FullName,[ref]$t,[ref]$e);Need ($e.Count -eq 0 -and $null -eq $a.Find({param($n)$n -is [Management.Automation.Language.ExitStatementAst]},$true))}}
